var i=120;var a=[{id:`cooking-120-01`,theoryId:120,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why do scrambled eggs turn rubbery after excessive heating?`,ua:`Чому яєчня-бовтанка стає гумовою після надмірного нагрівання?`},explanation:{en:`Overheated protein networks lose water, producing a firm, rubbery texture.`,ua:`Перегріті білкові структури втрачають воду й стають щільними та гумовими.`},options:[{id:`a`,text:{en:`Proteins tighten and expel moisture`,ua:`Білки ущільнюються та витискають вологу`}},{id:`b`,text:{en:`All fat evaporates into nothing`,ua:`Увесь жир випаровується без залишку`}},{id:`c`,text:{en:`The pan becomes colder with more heat`,ua:`Сковорода охолоджується від сильнішого жару`}}],answer:{optionIds:[`a`]}},{id:`cooking-120-02`,theoryId:120,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`An omelet is easier to fold before the egg surface has completely dried out.`,ua:`Омлет легше скласти, поки його поверхня не пересохла.`},explanation:{en:`Controlled setting maintains flexibility while still allowing an appropriate safe doneness.`,ua:`Контрольоване зсідання зберігає гнучкість, але потрібно досягати належної безпечної готовності.`},answer:{value:!0}},{id:`cooking-120-03`,theoryId:120,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match cooking choices to likely omelet results.`,ua:`Поєднайте прийоми з результатом приготування омлету.`},explanation:{en:`Heat and filling distribution determine the structure.`,ua:`Температура та розподіл начинки визначають структуру.`},leftItems:[{id:`l1`,text:{en:`Moderate controlled heat`,ua:`Помірний контрольований нагрів`}},{id:`l2`,text:{en:`Overlong high heat`,ua:`Надто довгий сильний жар`}},{id:`l3`,text:{en:`Evenly distributed filling`,ua:`Рівномірно розподілена начинка`}}],rightItems:[{id:`r3`,text:{en:`More consistent folding`,ua:`Рівномірніше складання`}},{id:`r2`,text:{en:`Dry rubbery egg`,ua:`Сухе гумове яйце`}},{id:`r1`,text:{en:`Gentler setting`,ua:`Делікатніше зсідання`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-120-04`,theoryId:120,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A diner at high risk of foodborne illness asks for very runny scrambled eggs. What is the safer plan?`,ua:`Людина з високим ризиком харчового отруєння просить дуже рідку яєчню. Який план безпечніший?`},explanation:{en:`FDA advice for higher-risk consumers favors fully cooked eggs and pasteurized products where undercooked eggs would otherwise be used.`,ua:`FDA радить людям із підвищеним ризиком повністю готувати яйця або використовувати пастеризовані продукти для страв із недостатньою тепловою обробкою.`},options:[{id:`a`,text:{en:`Cook until fully set as advised or use an appropriate pasteurized product under validated preparation`,ua:`Готувати до повного зсідання або використовувати належний пастеризований продукт за перевіреним режимом`}},{id:`b`,text:{en:`Use ordinary raw eggs with no safety check`,ua:`Використати звичайні сирі яйця без перевірки`}},{id:`c`,text:{en:`Assume color alone guarantees safety`,ua:`Вважати, що колір сам гарантує безпеку`}}],answer:{optionIds:[`a`]}},{id:`cooking-120-05`,theoryId:120,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which scrambled-egg technique is likely to produce an inferior texture?`,ua:`Яка техніка найімовірніше погіршить текстуру яєчні?`},explanation:{en:`Excessive heat tightens proteins and squeezes out water.`,ua:`Надмірний нагрів ущільнює білки й витискає воду.`},options:[{id:`a`,text:{en:`Use a controlled pan temperature`,ua:`Контролювати температуру сковороди`}},{id:`b`,text:{en:`Avoid prolonged overheating`,ua:`Не перегрівати довго`}},{id:`c`,text:{en:`Leave eggs cooking on maximum heat until dry and rubbery`,ua:`Тримати яйця на максимальному жарі до сухої гумової текстури`}}],answer:{optionIds:[`c`]}}];var n={theoryId:120,exercises:a};export{n as default,a as exercises,i as theoryId};